import{_ as t,c as s,o as r,j as e,a as o}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"原序","description":"周易口訣義 - 原序","frontmatter":{"title":"原序","description":"周易口訣義 - 原序"},"headers":[],"relativePath":"classics/koujueyi/002.md","filePath":"classics/koujueyi/002.md"}'),i={name:"classics/koujueyi/002.md"};function c(n,a,l,d,p,u){return r(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"原序",tabindex:"-1"},[o("原序 "),e("a",{class:"header-anchor",href:"#原序","aria-label":"Permalink to “原序”"},"​")],-1),e("p",null,"乾象既分，蒼牙應運，三才闡位，八卦昭彰。故能道濟不通，人用無極。自茲已降，祖述多家。田何傳於丁寬，京房得之焦貢。遂使異聞競起，蹖駮紛多，深乖述作之由，全誤聖人之見。若使廣求文句，博引證驗，浮誕日興，華偽滋蔓。誠謂周鼠終虧於鄭璞，魚目以混於隨珠。今則但舉宏機，纂其樞要。先以王注為宗，後約孔疏為理。至於卦繇六位，並備而釋之；彖以詳略，闕而不敘。大抵舉其六卷，分為上、下兩經，直以口訣為名，義決要為旨。或經象未顯，輒提緯以證文；傳疏未明，將考名以銷義。遂使疑祛理悟，還希述作之功；學寡難周，恥騰波於翰海云爾。",-1)])])}const f=t(i,[["render",c]]);export{_ as __pageData,f as default};
